#include "edudb.hpp"
#include <chrono>
#include <filesystem>
#include <fstream>
#include <future>
#include <iostream>
#include <map>
#include <set>
#include <thread>
using namespace edudb;
namespace fs=std::filesystem;
namespace {
std::size_t checks=0;json observations=json::array();
void require(bool b,const std::string& why){++checks;if(!b)throw std::runtime_error(why);}
json ok(Engine& e,const std::string& s,const std::string& sql){auto r=e.execute(s,sql);require(r.value("ok",false),sql+": "+r.dump());return r;}
void error(Engine& e,const std::string& s,const std::string& sql,const std::string& code){auto r=e.execute(s,sql);require(!r.value("ok",true)&&r["error"]["code"]==code,sql+": "+r.dump());}
void expect(Engine& e,const std::string& s,const std::string& sql,const json& rows){require(ok(e,s,sql)["rows"]==rows,"SQL result: "+sql);}
void wait_cluster_queue(Engine& e){const auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(3);while(std::chrono::steady_clock::now()<deadline){auto d=e.diagnostics();for(const auto& q:d["queues"])if(q["resource"].get<std::string>().rfind("cluster:",0)==0){require(!d["waits"].empty(),"Actual cluster lock queue has actual waiting graph");observations.push_back({{"kind","cluster_lock_wait"},{"queues",d["queues"]},{"waits",d["waits"]},{"locks",d["locks"]}});return;}std::this_thread::sleep_for(std::chrono::milliseconds(2));}throw std::runtime_error("Expected real cluster lock queue");}
void sql_lifecycle(const fs::path& path){json expected_a,expected_b;
    {Engine e(path.u8string(),3);auto s=e.open_session();ok(e,s,"CREATE CLUSTER c");ok(e,s,"CREATE TABLE a(id INTEGER PRIMARY KEY,dept INTEGER,name VARCHAR(20),payload BLOB) RECORD FORMAT FIXED");ok(e,s,"CREATE TABLE b(id INTEGER PRIMARY KEY,dept INTEGER,name VARCHAR(20),payload BLOB) RECORD FORMAT VARIABLE");ok(e,s,"INSERT INTO a VALUES(1,10,'学生甲',X'010203'),(2,NULL,'空码学生',NULL)");ok(e,s,"INSERT INTO b VALUES(1,10,'课程甲',NULL),(2,NULL,'空码课程',NULL)");ok(e,s,"ALTER TABLE a CLUSTER c(dept)");ok(e,s,"ALTER TABLE b CLUSTER c(dept)");
        auto shape=ok(e,s,"INSPECT CLUSTER c LIMIT 256")["inspection"];bool sharing=false;for(const auto& page:shape["pages"])sharing|=page["table_row_counts"].size()==2;require(sharing,"Actual SQL-created shared page contains two tableOID tags");observations.push_back({{"kind","actual_shared_heap"},{"inspection",shape}});require(ok(e,s,"DESCRIBE a")["record_layout"]["table_oid_prefix_bytes"]==8,"SQL DESCRIBE exposes actual shared record prefix");
        expect(e,s,"SELECT a.id,b.id FROM a INNER JOIN b ON a.dept=b.dept ORDER BY a.id,b.id",json::array({json::array({1,1})}));expect(e,s,"SELECT COUNT(*) FROM a WHERE dept=NULL",json::array({json::array({0})}));expect(e,s,"SELECT COUNT(*) FROM a WHERE dept IS NULL",json::array({json::array({1})}));
        ok(e,s,"BEGIN");ok(e,s,"SAVEPOINT original");ok(e,s,"UPDATE b SET dept=20 WHERE id=1");ok(e,s,"ALTER TABLE a NO CLUSTER");ok(e,s,"ROLLBACK TO original");expect(e,s,"SELECT a.id,b.id FROM a INNER JOIN b ON a.dept=b.dept ORDER BY a.id,b.id",json::array({json::array({1,1})}));require(ok(e,s,"DESCRIBE a")["record_layout"]["table_oid_prefix_bytes"]==8,"SQL savepoint restores membership and record format");ok(e,s,"COMMIT");
        ok(e,s,"BEGIN");ok(e,s,"SAVEPOINT rename_key");ok(e,s,"ALTER TABLE a RENAME COLUMN dept TO division");expect(e,s,"SELECT COUNT(*) FROM a WHERE division IS NULL",json::array({json::array({1})}));ok(e,s,"ROLLBACK TO rename_key");ok(e,s,"COMMIT");error(e,s,"ALTER TABLE a DROP COLUMN dept","DEPENDENT_OBJECT");
        ok(e,s,"CREATE TABLE suffix_member(id INTEGER PRIMARY KEY,dept INTEGER) CLUSTER c(dept) RECORD FORMAT VARIABLE");ok(e,s,"INSERT INTO suffix_member VALUES(1,10)");ok(e,s,"ALTER TABLE suffix_member NO CLUSTER");expect(e,s,"SELECT * FROM suffix_member",json::array({json::array({1,10})}));ok(e,s,"DROP TABLE suffix_member");
        ok(e,s,"BEGIN");ok(e,s,"DELETE FROM a WHERE id=1");error(e,s,"INSERT INTO b VALUES(1,10,'重复',NULL)","UNIQUE_VIOLATION");error(e,s,"SELECT * FROM a","TRANSACTION_ABORTED");ok(e,s,"ROLLBACK");expect(e,s,"SELECT COUNT(*) FROM a",json::array({json::array({2})}));
        auto imported=e.import_data(s,{{"format","csv"},{"table","a"},{"header",true},{"content","id,dept,name,payload\r\n3,10,CSV,\\N\r\n"}});require(imported.value("ok",false),"CSV member import: "+imported.dump());auto failed=e.import_data(s,{{"format","csv"},{"table","a"},{"header",true},{"content","id,dept,name,payload\r\n4,10,rollback,\\N\r\n1,10,duplicate,\\N\r\n"}});require(!failed.value("ok",true),"CSV duplicate batch rejected");expect(e,s,"SELECT COUNT(*) FROM a WHERE id=4",json::array({json::array({0})}));
        auto one=e.open_session(),two=e.open_session();ok(e,one,"BEGIN");ok(e,one,"SELECT COUNT(*) FROM a");ok(e,two,"BEGIN");ok(e,two,"SELECT COUNT(*) FROM b");std::map<std::string,std::set<std::uint64_t>> holders;auto lock_snapshot=e.diagnostics();for(const auto& lock:lock_snapshot["locks"])if(lock["resource"].get<std::string>().rfind("cluster:",0)==0&&lock["mode"]=="S")holders[lock["resource"]].insert(lock["tx_id"].get<std::uint64_t>());bool compatible=false;for(const auto& item:holders)compatible|=item.second.size()==2;require(compatible,"Two live Engine transactions hold same real cluster S simultaneously: "+lock_snapshot["locks"].dump());observations.push_back({{"kind","simultaneous_cluster_S"},{"locks",lock_snapshot["locks"]}});ok(e,two,"COMMIT");
        ok(e,two,"BEGIN");auto blocked=std::async(std::launch::async,[&]{return e.execute(two,"UPDATE b SET name='等待后更新' WHERE id=1");});wait_cluster_queue(e);ok(e,one,"COMMIT");require(blocked.get().value("ok",false),"Cluster X writer resumes after reader commit");ok(e,two,"COMMIT");
        ok(e,one,"BEGIN");std::string growth="INSERT INTO a VALUES ";for(int id=100;id<300;++id){if(id!=100)growth+=",";growth+="("+std::to_string(id)+",10,'growth',NULL)";}ok(e,one,growth);ok(e,two,"BEGIN");auto metadata_wait=std::async(std::launch::async,[&]{return e.execute(two,"UPDATE a SET name='after wait' WHERE id=299");});wait_cluster_queue(e);ok(e,one,"COMMIT");auto resumed=metadata_wait.get();require(resumed.value("ok",false)&&resumed["affected_rows"]==1,"Waited writer binds latest descriptor/index root after committing writer's growth");ok(e,two,"COMMIT");expect(e,s,"SELECT name FROM a WHERE id=299",json::array({json::array({"after wait"})}));auto expanded=ok(e,s,"INSPECT TABLE a INDEX \"__pk_a\"")["inspection"]["structure"];require(expanded["descriptor"]["height"]>1,"Metadata wait fixture really split the persisted primary tree");observations.push_back({{"kind","post_wait_latest_descriptor"},{"primary_height",expanded["descriptor"]["height"]},{"affected_rows",resumed["affected_rows"]}});ok(e,s,"DELETE FROM a WHERE id>=100");

        ok(e,one,"BEGIN");ok(e,one,"SELECT COUNT(*) FROM a");auto csv_wait=std::async(std::launch::async,[&]{return e.import_data(two,{{"format","csv"},{"table","b"},{"header",true},{"content","id,dept,name,payload\r\n10,10,CSVwait,\\N\r\n"}});});wait_cluster_queue(e);ok(e,one,"COMMIT");require(csv_wait.get().value("ok",false),"CSV writer uses the same real cluster guard");
        ok(e,one,"BEGIN");ok(e,one,"UPDATE a SET name='temporary' WHERE id=1");auto csv_read_wait=std::async(std::launch::async,[&]{return e.export_data(two,{{"format","csv"},{"table","b"}});});wait_cluster_queue(e);ok(e,one,"ROLLBACK");auto exported_csv=csv_read_wait.get();require(exported_csv.value("ok",false)&&exported_csv["row_count"]==3,"CSV reader waits on cluster guard and exports exact member rows");
        ok(e,one,"BEGIN");ok(e,one,"UPDATE a SET name='verify wait' WHERE id=1");auto verify_wait=std::async(std::launch::async,[&]{return e.execute(two,"VERIFY");});wait_cluster_queue(e);ok(e,one,"COMMIT");require(verify_wait.get().value("ok",false),"VERIFY uses unified real cluster guard");
        ok(e,s,"CREATE CLUSTER d");ok(e,s,"CREATE TABLE x(id INTEGER PRIMARY KEY,dept INTEGER)");ok(e,s,"CREATE TABLE y(id INTEGER PRIMARY KEY,dept INTEGER)");ok(e,s,"INSERT INTO x VALUES(1,10)");ok(e,s,"INSERT INTO y VALUES(1,10)");ok(e,s,"ALTER TABLE x CLUSTER d(dept)");ok(e,s,"ALTER TABLE y CLUSTER d(dept)");
        ok(e,one,"BEGIN");ok(e,one,"UPDATE a SET name='first' WHERE id=1");ok(e,two,"BEGIN");ok(e,two,"UPDATE x SET dept=11 WHERE id=1");auto cycle=std::async(std::launch::async,[&]{return e.execute(one,"UPDATE x SET dept=12 WHERE id=1");});wait_cluster_queue(e);auto victim=e.execute(two,"UPDATE b SET name='loser' WHERE id=1");require(!victim.value("ok",true)&&victim["error"]["code"]=="DEADLOCK","Actual two-cluster cycle aborts greatest transaction id");auto deadlock_snapshot=e.diagnostics();json cycles=json::array();for(const auto& event:deadlock_snapshot["events"])if(event["kind"]=="deadlock_cycle")cycles.push_back(event);require(!cycles.empty(),"Actual wait graph cycle/victim are preserved by lock manager");observations.push_back({{"kind","two_cluster_deadlock"},{"cycles",cycles},{"victim_result",victim}});require(cycle.get().value("ok",false),"Surviving cluster writer resumes after victim rollback");ok(e,one,"COMMIT");ok(e,two,"ROLLBACK");expect(e,s,"SELECT dept FROM x",json::array({json::array({12})}));
        ok(e,s,"CREATE CLUSTER empty_c");ok(e,s,"CREATE TABLE temp_member(k VARCHAR(8))");ok(e,s,"ALTER TABLE temp_member CLUSTER empty_c(k)");ok(e,s,"ALTER TABLE temp_member NO CLUSTER");ok(e,s,"DROP TABLE temp_member");
        expected_a=ok(e,s,"SELECT * FROM a ORDER BY id")["rows"];expected_b=ok(e,s,"SELECT * FROM b ORDER BY id")["rows"];auto dump=e.export_data(s,{{"format","sql"}});require(dump.value("ok",false)&&dump["content"].get<std::string>().find("CREATE CLUSTER")!=std::string::npos,"SQL export preserves native cluster dependencies");Engine copy((path/"logical-copy").u8string(),3);auto cs=copy.open_session();auto restored=copy.import_data(cs,{{"format","sql"},{"content",dump["content"]}});require(restored.value("ok",false),"Logical cluster recreation: "+restored.dump());expect(copy,cs,"SELECT * FROM a ORDER BY id",expected_a);expect(copy,cs,"SELECT * FROM b ORDER BY id",expected_b);ok(copy,cs,"INSPECT CLUSTER c");ok(copy,cs,"VERIFY");copy.close_session(cs);
        ok(e,s,"VERIFY");e.close_session(one);e.close_session(two);e.close_session(s);
    }
    {Engine e(path.u8string(),2);auto s=e.open_session();expect(e,s,"SELECT * FROM a ORDER BY id",expected_a);expect(e,s,"SELECT * FROM b ORDER BY id",expected_b);ok(e,s,"ALTER TABLE a NO CLUSTER");expect(e,s,"SELECT * FROM a ORDER BY id",expected_a);ok(e,s,"DROP TABLE b");ok(e,s,"DROP CLUSTER c");ok(e,s,"VERIFY");e.close_session(s);}
}
}
int main(){auto root=fs::temp_directory_path()/("edudb-cluster-sql-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));try{fs::create_directory(root);std::ofstream(root/"owned-test.marker")<<"cluster SQL";sql_lifecycle(root/"db");require(fs::equivalent(root.parent_path(),fs::temp_directory_path())&&root.filename().string().rfind("edudb-cluster-sql-",0)==0&&fs::exists(root/"owned-test.marker"),"Owned test cleanup");fs::remove_all(root);std::cout<<"OBSERVATIONS "<<observations.dump()<<"\n";std::cout<<"PASS cluster SQL "<<checks<<" checks: nativeDDL, NULL, transactions/savepoints, CSV/logical I/O, real cluster locks/deadlock and reopen\n";return 0;}catch(const std::exception& error){std::cerr<<"FAIL cluster SQL after "<<checks<<" checks: "<<error.what()<<"; evidence at "<<root.u8string()<<"\n";return 1;}}
